    albedo *= 1.0 - stain * 0.45 - smoothstep(0.6, 0.0, y) * 0.3;
    albedo = mix(albedo, vec3(0.25, 0.3, 0.12), drip * 0.4);
    gloss = 0.5 * (1.0 - grout) * (1.0 - stain);
